import { Controller } from "stimulus";
import showHttpError from "../../webpacker/js/services/show_http_error";

export default class extends Controller {
  static values = { url: String };

  async resend() {
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute("content");

    try {
      const response = await fetch(this.urlValue, {
        method: "POST",
        headers: { "X-CSRF-Token": csrfToken },
      });
      if (!response.ok) showHttpError(response.status);
    } catch {
      // No response at all, e.g. network failure
      showHttpError();
    }
  }
}
```

- **Error messages:** the repo already has a helper, `app/webpacker/js/services/show_http_error.js`, that does exactly this mapping: 401 shows `errors.unauthorized.message`, no status shows `errors.network_error.message`, and 500 or above shows `errors.general_error.message`. I reused it instead of writing the checks again. Other 4xx errors show no alert, which is what the helper already does.
- **No response:** if `fetch` fails outright (for example, a network failure), the controller calls the helper with no status, so the user gets the network error message.
- **CSRF token:** I added the `X-CSRF-Token` header, as the other `fetch` POSTs in the codebase do. Without it, Rails would reject the request.

The component's template needs to attach the controller with `data-controller`, set the URL with `data-…-url-value`, and wire the button with `data-action="…#resend"`.
